#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry trigo. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Variables A B C : 'rV[R]_2. Hypothesis on_circle : exists O : 'rV[R]_2, exists r : R, 0 < r /\ norm (A - O) = r /\ norm (B - O) = r /\ norm (C - O) = r. Hypothesis length_BC : norm (B - C) = 3. Hypothesis angle_ABC : let theta := acos (((A - B) *m (C - B)^T) 0 0 / (norm (A - B) * norm (C - B))) in theta = (10 * PI) / 180. Definition sector_area O P Q := let r := norm (P - O) in let theta := acos (((Q - O) *m (P - O)^T) 0 0 / (norm (Q - O) * r)) in theta / 2 * r ^+ 2. Theorem sector_area_BAC : forall O, on_circle -> sector_area O B A = PI / 4 * (norm (A - O)) ^+ 2. Proof. by []. Qed.
